def solve_n_queens(n):
    """Solve the N-Queens problem using backtracking."""
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row] == i:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i] == j:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i] == j:
                return False

        return True

    def solve(board, col):
        if col >= n:
            return True

        for row in range(n):
            if is_safe(board, row, col):
                board[row] = col
                if solve(board, col + 1):
                    return True
                board[row] = -1

        return False

    board = [-1] * n
    if solve(board, 0):
        # Convert to the required format: board[row] = col
        # We need to return a list where the i-th element is the column of the queen in row i
        result = [0] * n
        for row in range(n):
            result[row] = board[row]
        return result
    return None

# Solve for 21 queens
solution = solve_n_queens(21)
print(solution)

# Verify the solution
def verify_solution(solution):
    n = len(solution)
    # Check all queens are in valid positions
    for i in range(n):
        if solution[i] < 0 or solution[i] >= n:
            return False

    # Check no two queens share the same column
    if len(set(solution)) != n:
        return False

    # Check no two queens share the same diagonal
    for i in range(n):
        for j in range(i+1, n):
            if abs(solution[i] - solution[j]) == abs(i - j):
                return False

    return True

print("Valid:", verify_solution(solution))
